begin;

-- ---------- เพิ่มหมวดหมู่ ----------
insert into categories (branch_id, code, name_th, sort_order)
select '448937cf-58c5-4007-b57b-6a8bcf46c2fe', 'renewable_energy', 'พลังงานทดแทน/โซลาร์เซลล์ (Renewable Energy)', 12
