);

-- ---------- เพิ่มคำถาม (33 ข้อ) ----------
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เซลล์แสงอาทิตย์ (Solar Cell หรือ Photovoltaic Cell) ผลิตกระแสไฟฟ้าจากแสงอาทิตย์ได้ด้วยหลักการใด', 'อาศัยปรากฏการณ์โฟโตวอลเทอิก (Photovoltaic Effect) ที่เกิดขึ้นในสารกึ่งตัวนำ เมื่อโฟตอนของแสงมีพลังงานเพียงพอกระทบกับสารกึ่งตัวนำ จะกระตุ้นให้อิเล็กตรอนหลุดออกจากพันธะและเคลื่อนที่ผ่านรอยต่อ P-N ทำให้เกิดกระแสไฟฟ้าไหลในวงจรภายนอกเมื่อต่อโหลดเข้ากับขั้วของเซลล์', 'เซลล์แสงอาทิตย์ผลิตไฟฟ้ากระแสตรง (DC) โดยตรง จึงจำเป็นต้องมีอินเวอร์เตอร์แปลงเป็นไฟฟ้ากระแสสลับก่อนเชื่อมต่อกับระบบไฟฟ้าหรือใช้งานกับอุปกรณ์ไฟฟ้ากระแสสลับทั่วไป', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เซลล์แสงอาทิตย์ (Solar Cell หรือ Photovoltaic Cell) ผลิตกระแสไฟฟ้าจากแสงอาทิตย์ได้ด้วยหลักการใด'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'แผงโซลาร์เซลล์ชนิด Monocrystalline และ Polycrystalline แตกต่างกันอย่างไรในโครงสร้างและประสิทธิภาพ', 'แผงชนิด Monocrystalline ผลิตจากผลึกซิลิคอนเดี่ยวที่มีโครงสร้างเป็นระเบียบสม่ำเสมอ ทำให้มีประสิทธิภาพการแปลงพลังงานสูงกว่าและมีสีเข้มสม่ำเสมอ ส่วนแผงชนิด Polycrystalline ผลิตจากผลึกซิลิคอนหลายผลึกหลอมรวมกัน มีประสิทธิภาพต่ำกว่าเล็กน้อยแต่มีต้นทุนการผลิตที่ต่ำกว่า', 'การเลือกใช้ขึ้นอยู่กับพื้นที่ติดตั้งที่มีจำกัดหรือไม่ หากพื้นที่จำกัดและต้องการกำลังผลิตสูงสุดต่อพื้นที่ อาจเลือกใช้ Monocrystalline แม้จะมีต้นทุนต่อวัตต์สูงกว่า', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'แผงโซลาร์เซลล์ชนิด Monocrystalline และ Polycrystalline แตกต่างกันอย่างไรในโครงสร้างและประสิทธิภาพ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'แผงโซลาร์เซลล์ชนิดฟิล์มบาง (Thin Film) มีข้อดีและข้อจำกัดอย่างไรเมื่อเทียบกับแผงชนิดผลึกซิลิคอน', 'แผงฟิล์มบางมีน้ำหนักเบา มีความยืดหยุ่นในการติดตั้งบนพื้นผิวโค้งได้ และมีประสิทธิภาพในสภาวะแสงน้อยหรืออุณหภูมิสูงดีกว่าในบางกรณี แต่มีข้อจำกัดคือประสิทธิภาพการแปลงพลังงานต่อพื้นที่ต่ำกว่าแผงผลึกซิลิคอนอย่างมาก จึงต้องใช้พื้นที่ติดตั้งมากกว่าสำหรับกำลังผลิตเท่ากัน', 'แผงฟิล์มบางจึงมักเหมาะกับการใช้งานเฉพาะทางที่ต้องการความยืดหยุ่นหรือน้ำหนักเบา มากกว่าการใช้งานติดตั้งบนหลังคาทั่วไปที่มีพื้นที่จำกัดและต้องการกำลังผลิตสูงสุดต่อพื้นที่', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'แผงโซลาร์เซลล์ชนิดฟิล์มบาง (Thin Film) มีข้อดีและข้อจำกัดอย่างไรเมื่อเทียบกับแผงชนิดผลึกซิลิคอน'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ค่าสัมประสิทธิ์อุณหภูมิ (Temperature Coefficient) ของแผงโซลาร์เซลล์มีความหมายอย่างไร และมีผลต่อการผลิตไฟฟ้าอย่างไร', 'บ่งบอกอัตราการเปลี่ยนแปลงของกำลังไฟฟ้าที่ผลิตได้ต่อการเปลี่ยนแปลงอุณหภูมิของแผง ซึ่งโดยทั่วไปเป็นค่าลบ หมายความว่าเมื่ออุณหภูมิของแผงสูงขึ้น กำลังไฟฟ้าที่ผลิตได้จะลดลง แม้ความเข้มแสงจะเท่าเดิมก็ตาม', 'ในประเทศเขตร้อนที่มีอุณหภูมิสูง แผงโซลาร์เซลล์จึงมักผลิตไฟฟ้าได้ต่ำกว่าค่าพิกัดที่ระบุไว้ ณ สภาวะทดสอบมาตรฐาน (ซึ่งกำหนดที่อุณหภูมิ 25 องศาเซลเซียส) ทำให้การออกแบบระบบต้องคำนึงถึงผลกระทบนี้และเผื่อระยะห่างการติดตั้งเพื่อการระบายความร้อนที่เพียงพอ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ค่าสัมประสิทธิ์อุณหภูมิ (Temperature Coefficient) ของแผงโซลาร์เซลล์มีความหมายอย่างไร และมีผลต่อการผลิตไฟฟ้าอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดแผงโซลาร์เซลล์จึงมักติดตั้งไดโอดบายพาส (Bypass Diode) ในแต่ละกลุ่มเซลล์ย่อยภายในแผง', 'เพื่อป้องกันความเสียหายที่อาจเกิดขึ้นเมื่อบางส่วนของแผงถูกบดบังแสง (Partial Shading) เซลล์ที่ถูกบังจะทำหน้าที่เป็นความต้านทานแทนที่จะผลิตกระแส หากไม่มีไดโอดบายพาส กระแสจากเซลล์ส่วนที่เหลือจะถูกบังคับให้ไหลผ่านเซลล์ที่ถูกบังนี้ ก่อให้เกิดความร้อนสูงเฉพาะจุด (Hot Spot) ที่อาจทำลายเซลล์นั้นได้', 'ไดโอดบายพาสให้เส้นทางลัดสำหรับกระแสไหลข้ามกลุ่มเซลล์ที่มีปัญหา แทนที่จะบังคับให้ไหลผ่าน ซึ่งช่วยปกป้องแผงและยังช่วยลดการสูญเสียกำลังผลิตโดยรวมเมื่อมีการบังแสงบางส่วนด้วย', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดแผงโซลาร์เซลล์จึงมักติดตั้งไดโอดบายพาส (Bypass Diode) ในแต่ละกลุ่มเซลล์ย่อยภายในแผง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'อินเวอร์เตอร์แบบ String Inverter และแบบ Central Inverter ในระบบโซลาร์เซลล์ขนาดใหญ่แตกต่างกันอย่างไร', 'String Inverter ทำหน้าที่แปลงไฟฟ้าจากแต่ละสายอนุกรม (String) ของแผงแยกจากกัน ทำให้หากแผงในสายหนึ่งมีปัญหาหรือถูกบดบัง จะไม่กระทบต่อการผลิตไฟฟ้าของสายอื่น ส่วน Central Inverter รวบรวมไฟฟ้าจากหลายสายเข้าด้วยกันก่อนแปลงผ่านอินเวอร์เตอร์ตัวเดียวขนาดใหญ่ ซึ่งมีต้นทุนต่อวัตต์ต่ำกว่าแต่มีความเสี่ยงจากจุดล้มเหลวเดียว (Single Point of Failure) สูงกว่า', 'การเลือกใช้ขึ้นอยู่กับขนาดโครงการและลักษณะพื้นที่ติดตั้ง ระบบขนาดใหญ่มากมักใช้ Central Inverter เพื่อลดต้นทุน ในขณะที่ระบบที่มีความเสี่ยงจากการบดบังแสงไม่สม่ำเสมอมักเลือกใช้ String Inverter เพื่อประสิทธิภาพที่ดีกว่า', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'อินเวอร์เตอร์แบบ String Inverter และแบบ Central Inverter ในระบบโซลาร์เซลล์ขนาดใหญ่แตกต่างกันอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ไมโครอินเวอร์เตอร์ (Microinverter) แตกต่างจาก String Inverter อย่างไร และมีข้อดีเฉพาะตัวอะไร', 'ไมโครอินเวอร์เตอร์ติดตั้งแยกอิสระที่แผงแต่ละแผ่น ทำการแปลงไฟฟ้ากระแสตรงเป็นกระแสสลับตั้งแต่ระดับแผงเดี่ยว ทำให้แต่ละแผงทำงานที่จุดกำลังไฟฟ้าสูงสุดของตัวเองอย่างอิสระ ไม่ได้รับผลกระทบจากแผงอื่นที่อาจถูกบดบังหรือมีประสิทธิภาพต่ำกว่า', 'ระบบนี้เหมาะกับพื้นที่ติดตั้งที่มีการบดบังแสงไม่สม่ำเสมอในบางช่วงเวลา เช่น มีเงาต้นไม้บางส่วน แม้จะมีต้นทุนต่อวัตต์สูงกว่าระบบ String Inverter แต่สามารถให้ผลผลิตพลังงานรวมสูงกว่าในสภาวะที่มีการบดบังแสงบางส่วน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ไมโครอินเวอร์เตอร์ (Microinverter) แตกต่างจาก String Inverter อย่างไร และมีข้อดีเฉพาะตัวอะไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ระบบโซลาร์เซลล์แบบเชื่อมต่อกับระบบไฟฟ้า (Grid-tied) แตกต่างจากระบบแบบอิสระ (Off-grid) อย่างไร', 'ระบบ Grid-tied เชื่อมต่อและทำงานร่วมกับระบบไฟฟ้าหลัก สามารถใช้ไฟฟ้าจากระบบหลักเสริมเมื่อผลิตไม่เพียงพอ และอาจขายไฟฟ้าส่วนเกินคืนเข้าระบบได้ในบางกรณี แต่ต้องหยุดจ่ายไฟทันทีเมื่อระบบหลักดับ (ด้วยฟังก์ชัน Anti-islanding) ส่วนระบบ Off-grid ทำงานเป็นอิสระอย่างสมบูรณ์โดยไม่เชื่อมต่อกับระบบไฟฟ้าหลัก ต้องอาศัยระบบกักเก็บพลังงาน (แบตเตอรี่) เพื่อสำรองไฟฟ้าใช้ในช่วงที่ไม่มีแสงอาทิตย์', 'ระบบ Off-grid เหมาะกับพื้นที่ห่างไกลที่ไม่มีระบบไฟฟ้าเข้าถึง หรือระบบที่ต้องการความเป็นอิสระจากระบบไฟฟ้าหลักอย่างสมบูรณ์ แม้จะมีต้นทุนสูงกว่าเนื่องจากต้องมีระบบแบตเตอรี่ขนาดใหญ่เพียงพอรองรับการใช้งานในช่วงที่ไม่มีแสงอาทิตย์', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ระบบโซลาร์เซลล์แบบเชื่อมต่อกับระบบไฟฟ้า (Grid-tied) แตกต่างจากระบบแบบอิสระ (Off-grid) อย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ระบบโซลาร์เซลล์แบบไฮบริด (Hybrid System) มีลักษณะการทำงานอย่างไรที่แตกต่างจากทั้งระบบ Grid-tied และ Off-grid', 'ระบบไฮบริดเชื่อมต่อกับระบบไฟฟ้าหลักเหมือน Grid-tied แต่มีระบบแบตเตอรี่กักเก็บพลังงานร่วมด้วยเหมือน Off-grid ทำให้สามารถใช้พลังงานที่เก็บสะสมไว้ในช่วงที่ไม่มีแสงอาทิตย์หรือไฟฟ้าหลักดับ (Backup Power) โดยไม่ต้องพึ่งพาระบบไฟฟ้าหลักทั้งหมด ในขณะที่ยังคงสามารถเชื่อมต่อกับระบบหลักได้ในสภาวะปกติ', 'ระบบไฮบริดได้รับความนิยมเพิ่มขึ้นในพื้นที่ที่มีปัญหาไฟฟ้าดับบ่อยหรือต้องการความมั่นคงของแหล่งจ่ายไฟฟ้าเพิ่มเติม แม้จะมีต้นทุนสูงกว่าระบบ Grid-tied ธรรมดาเนื่องจากต้องมีทั้งอินเวอร์เตอร์แบบไฮบริดและระบบแบตเตอรี่', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ระบบโซลาร์เซลล์แบบไฮบริด (Hybrid System) มีลักษณะการทำงานอย่างไรที่แตกต่างจากทั้งระบบ Grid-tied และ Off-grid'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การจัดเรียงแผงโซลาร์เซลล์แบบอนุกรม (Series) และแบบขนาน (Parallel) ในอาร์เรย์ ให้ผลต่อแรงดันและกระแสรวมของระบบอย่างไร', 'การต่อแบบอนุกรมทำให้แรงดันรวมเพิ่มขึ้นตามจำนวนแผง แต่กระแสยังคงเท่ากับกระแสของแผงเดี่ยว ส่วนการต่อแบบขนานทำให้กระแสรวมเพิ่มขึ้นตามจำนวนสาย แต่แรงดันยังคงเท่ากับแรงดันของสายเดี่ยว ซึ่งเป็นหลักการเดียวกับการต่อแบตเตอรี่ที่กล่าวถึงในหมวดวงจรไฟฟ้า', 'การออกแบบอาร์เรย์ต้องคำนึงถึงพิกัดแรงดันสูงสุดที่อินเวอร์เตอร์รับได้ (จำกัดจำนวนแผงต่ออนุกรม) และพิกัดกระแสสูงสุดที่สายไฟและอุปกรณ์ป้องกันรองรับได้ (จำกัดจำนวนสายขนาน) ให้เหมาะสมกับอินเวอร์เตอร์ที่เลือกใช้', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การจัดเรียงแผงโซลาร์เซลล์แบบอนุกรม (Series) และแบบขนาน (Parallel) ในอาร์เรย์ ให้ผลต่อแรงดันและกระแสรวมของระบบอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'อัตราการเสื่อมสภาพ (Degradation Rate) ของแผงโซลาร์เซลล์คืออะไร และมีความสำคัญอย่างไรในการประเมินผลผลิตพลังงานระยะยาว', 'คืออัตราที่ประสิทธิภาพการผลิตไฟฟ้าของแผงลดลงตามอายุการใช้งาน ซึ่งเกิดจากการเสื่อมสภาพของวัสดุตามธรรมชาติเมื่อสัมผัสแสงแดดและสภาพอากาศเป็นเวลานาน ผู้ผลิตมักรับประกันว่าแผงจะยังคงผลิตไฟฟ้าได้ไม่ต่ำกว่าเปอร์เซ็นต์ที่กำหนดของกำลังผลิตเริ่มต้นเมื่อครบอายุการรับประกัน เช่น 25 หรือ 30 ปี', 'การประเมินความคุ้มค่าทางเศรษฐศาสตร์ของโครงการโซลาร์เซลล์ในระยะยาวต้องคำนึงถึงอัตราการเสื่อมสภาพนี้ เพราะผลผลิตพลังงานในปีท้ายๆ ของอายุโครงการจะต่ำกว่าปีแรกอย่างมีนัยสำคัญ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'อัตราการเสื่อมสภาพ (Degradation Rate) ของแผงโซลาร์เซลล์คืออะไร และมีความสำคัญอย่างไรในการประเมินผลผลิตพลังงานระยะยาว'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การติดตั้งแผงโซลาร์เซลล์ในมุมเอียงและทิศทางที่เหมาะสม มีความสำคัญอย่างไรต่อผลผลิตพลังงานที่ได้', 'มุมเอียงและทิศทางที่เหมาะสมช่วยให้แผงรับแสงอาทิตย์ได้มากที่สุดตลอดทั้งปี โดยทั่วไปมุมเอียงที่เหมาะสมมักใกล้เคียงกับละติจูดของพื้นที่ติดตั้ง และทิศทางที่เหมาะสมสำหรับซีกโลกเหนือมักหันไปทางทิศใต้ (หรือทิศเหนือสำหรับซีกโลกใต้) เพื่อรับแสงอาทิตย์ได้ตลอดวันอย่างสม่ำเสมอที่สุด', 'ในทางปฏิบัติ การติดตั้งบนหลังคาที่มีทิศทางและมุมเอียงคงที่ตามโครงสร้างอาคารเดิม อาจไม่ใช่มุมที่เหมาะสมที่สุดตามทฤษฎี แต่ก็ยังคงให้ผลผลิตพลังงานที่ยอมรับได้ในทางปฏิบัติ โดยความสูญเสียจากมุมที่ไม่เหมาะสมมักไม่มากเกินไปหากเบี่ยงเบนไม่มากนัก', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การติดตั้งแผงโซลาร์เซลล์ในมุมเอียงและทิศทางที่เหมาะสม มีความสำคัญอย่างไรต่อผลผลิตพลังงานที่ได้'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ระบบติดตามดวงอาทิตย์ (Solar Tracker) มีประโยชน์อย่างไรในการเพิ่มผลผลิตพลังงานของระบบโซลาร์เซลล์', 'ระบบติดตามดวงอาทิตย์ปรับมุมของแผงให้หันเข้าหาดวงอาทิตย์โดยตรงตลอดทั้งวัน แทนที่จะติดตั้งในมุมคงที่ ช่วยเพิ่มปริมาณแสงที่ตกกระทบแผงในมุมที่เหมาะสมที่สุดตลอดเวลา ทำให้ผลผลิตพลังงานรวมสูงขึ้นเมื่อเทียบกับระบบติดตั้งแบบมุมคงที่ที่มีพื้นที่แผงเท่ากัน', 'อย่างไรก็ตาม ระบบติดตามดวงอาทิตย์มีต้นทุนการติดตั้งและบำรุงรักษาสูงกว่าระบบมุมคงที่ เนื่องจากมีชิ้นส่วนกลไกเคลื่อนไหวเพิ่มเติม จึงต้องพิจารณาความคุ้มค่าทางเศรษฐศาสตร์เปรียบเทียบกับผลผลิตพลังงานที่เพิ่มขึ้นในแต่ละโครงการ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ระบบติดตามดวงอาทิตย์ (Solar Tracker) มีประโยชน์อย่างไรในการเพิ่มผลผลิตพลังงานของระบบโซลาร์เซลล์'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การหักลบหน่วยไฟฟ้า (Net Metering) แตกต่างจากการซื้อขายไฟฟ้าแบบ Net Billing อย่างไร', 'ระบบ Net Metering หักลบปริมาณไฟฟ้าที่ผลิตได้จากระบบพลังงานทดแทนกับปริมาณไฟฟ้าที่ใช้จากระบบหลักโดยตรงเป็นหน่วยไฟฟ้า (kWh) ก่อนคิดค่าไฟฟ้า ในขณะที่ Net Billing คิดมูลค่าไฟฟ้าที่ผลิตได้และไฟฟ้าที่ใช้แยกกันตามราคาที่อาจแตกต่างกัน (เช่น ราคาขายไฟฟ้าคืนต่ำกว่าราคาซื้อไฟฟ้า) แล้วจึงหักลบเป็นมูลค่าเงินแทนที่จะเป็นหน่วยไฟฟ้าโดยตรง', 'นโยบายที่ใช้ในแต่ละประเทศหรือแต่ละช่วงเวลาอาจแตกต่างกัน ซึ่งมีผลอย่างมากต่อความคุ้มค่าทางเศรษฐศาสตร์ของการติดตั้งระบบพลังงานทดแทน ผู้ออกแบบระบบจึงต้องทราบนโยบายที่บังคับใช้ในพื้นที่นั้นก่อนประเมินความคุ้มค่าของโครงการ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การหักลบหน่วยไฟฟ้า (Net Metering) แตกต่างจากการซื้อขายไฟฟ้าแบบ Net Billing อย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'สัญญาซื้อขายไฟฟ้า (Power Purchase Agreement, PPA) ในบริบทของโครงการพลังงานทดแทน มีลักษณะอย่างไร', 'เป็นสัญญาระยะยาวระหว่างผู้ผลิตไฟฟ้าจากพลังงานทดแทนกับผู้ซื้อไฟฟ้า (เช่น การไฟฟ้าหรือผู้ใช้ไฟฟ้าเอกชน) กำหนดราคาและเงื่อนไขการซื้อขายไฟฟ้าไว้ล่วงหน้าเป็นระยะเวลานาน เช่น 15-25 ปี ซึ่งช่วยให้ผู้ผลิตไฟฟ้ามีความมั่นใจในรายได้ที่แน่นอนเพื่อขอสินเชื่อลงทุนก่อสร้างโครงการ', 'รูปแบบ PPA มีความหลากหลาย เช่น การกำหนดราคาคงที่ตลอดสัญญา หรือราคาที่ปรับตามดัชนีต่างๆ ซึ่งมีผลต่อความเสี่ยงและผลตอบแทนของทั้งผู้ผลิตและผู้ซื้อไฟฟ้าที่แตกต่างกันไป', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'สัญญาซื้อขายไฟฟ้า (Power Purchase Agreement, PPA) ในบริบทของโครงการพลังงานทดแทน มีลักษณะอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'กังหันลม (Wind Turbine) ผลิตไฟฟ้าจากพลังงานลมด้วยหลักการพื้นฐานอย่างไร', 'ใบพัดของกังหันลมรับพลังงานจลน์จากการเคลื่อนที่ของอากาศ แปลงเป็นพลังงานกลในการหมุนของเพลา ซึ่งเชื่อมต่อกับเครื่องกำเนิดไฟฟ้า (มักผ่านชุดเกียร์ทดรอบเพื่อเพิ่มความเร็วรอบให้เหมาะกับเครื่องกำเนิดไฟฟ้า) เพื่อแปลงพลังงานกลเป็นพลังงานไฟฟ้าในที่สุด', 'กำลังไฟฟ้าที่ผลิตได้จากกังหันลมแปรผันตามกำลังสามของความเร็วลม ทำให้แม้ความเร็วลมเปลี่ยนแปลงเพียงเล็กน้อยก็มีผลกระทบอย่างมากต่อกำลังไฟฟ้าที่ผลิตได้ การเลือกพื้นที่ติดตั้งที่มีศักยภาพลมสูงและสม่ำเสมอจึงมีความสำคัญมากต่อความคุ้มค่าของโครงการ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'กังหันลม (Wind Turbine) ผลิตไฟฟ้าจากพลังงานลมด้วยหลักการพื้นฐานอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'กังหันลมแบบแกนนอน (Horizontal Axis Wind Turbine) และแบบแกนตั้ง (Vertical Axis Wind Turbine) แตกต่างกันอย่างไร', 'กังหันแบบแกนนอนมีแกนหมุนขนานกับพื้นดินและทิศทางลม เป็นแบบที่พบเห็นทั่วไปในฟาร์มกังหันลมขนาดใหญ่ มีประสิทธิภาพสูงแต่ต้องมีระบบหันหน้าเข้าหาทิศทางลม (Yaw System) ส่วนกังหันแบบแกนตั้งมีแกนหมุนตั้งฉากกับพื้นดิน สามารถรับลมได้จากทุกทิศทางโดยไม่ต้องมีระบบหันหน้า แต่โดยทั่วไปมีประสิทธิภาพต่ำกว่าแบบแกนนอน', 'กังหันแบบแกนตั้งมักเหมาะกับการใช้งานขนาดเล็กในพื้นที่ที่มีทิศทางลมไม่แน่นอน เช่น พื้นที่เมืองที่มีอาคารบดบัง ในขณะที่กังหันแบบแกนนอนขนาดใหญ่นิยมใช้ในฟาร์มกังหันลมเชิงพาณิชย์ที่ต้องการประสิทธิภาพสูงสุด', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'กังหันลมแบบแกนนอน (Horizontal Axis Wind Turbine) และแบบแกนตั้ง (Vertical Axis Wind Turbine) แตกต่างกันอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดกังหันลมจึงต้องมีระบบควบคุมมุมใบพัด (Pitch Control) หรือระบบหยุดการทำงานเมื่อความเร็วลมสูงเกินพิกัด (Cut-out Speed)', 'เพื่อป้องกันความเสียหายทางกลไกที่อาจเกิดขึ้นเมื่อความเร็วลมสูงเกินกว่าที่โครงสร้างและเครื่องกำเนิดไฟฟ้าจะรองรับได้อย่างปลอดภัย ระบบควบคุมมุมใบพัดช่วยปรับมุมรับลมให้ลดแรงที่กระทำต่อใบพัดในสภาวะลมแรง ในขณะที่ระบบ Cut-out จะหยุดการทำงานทั้งหมดเมื่อความเร็วลมสูงเกินขีดจำกัดความปลอดภัย', 'กังหันลมจึงมีช่วงความเร็วลมที่ทำงานได้อย่างมีประสิทธิภาพ (ระหว่าง Cut-in Speed ที่เริ่มผลิตไฟฟ้าได้ กับ Cut-out Speed ที่ต้องหยุดทำงาน) ซึ่งเป็นข้อมูลสำคัญในการประเมินศักยภาพการผลิตไฟฟ้าของพื้นที่ที่พิจารณาติดตั้ง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดกังหันลมจึงต้องมีระบบควบคุมมุมใบพัด (Pitch Control) หรือระบบหยุดการทำงานเมื่อความเร็วลมสูงเกินพิกัด (Cut-out Speed)'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'พลังงานชีวมวล (Biomass Energy) ผลิตไฟฟ้าได้ด้วยกระบวนการหลักอย่างไร', 'โดยทั่วไปนำวัสดุชีวมวล เช่น เศษวัสดุการเกษตรหรือเศษไม้ มาเผาไหม้เพื่อผลิตความร้อนสำหรับต้มน้ำให้เป็นไอน้ำแรงดันสูง แล้วนำไอน้ำไปขับกังหันไอน้ำที่เชื่อมต่อกับเครื่องกำเนิดไฟฟ้า ซึ่งเป็นหลักการเดียวกับโรงไฟฟ้าพลังความร้อนทั่วไป เพียงแต่เปลี่ยนแหล่งเชื้อเพลิงเป็นชีวมวลแทนเชื้อเพลิงฟอสซิล', 'พลังงานชีวมวลถือเป็นพลังงานทดแทนที่มีข้อได้เปรียบสำคัญคือสามารถผลิตไฟฟ้าได้อย่างต่อเนื่องตามความต้องการ (Dispatchable) ต่างจากพลังงานแสงอาทิตย์และลมที่ผันแปรตามสภาพอากาศธรรมชาติ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'พลังงานชีวมวล (Biomass Energy) ผลิตไฟฟ้าได้ด้วยกระบวนการหลักอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'พลังงานก๊าซชีวภาพ (Biogas) แตกต่างจากพลังงานชีวมวลแบบเผาไหม้โดยตรงอย่างไร', 'ก๊าซชีวภาพผลิตจากกระบวนการย่อยสลายสารอินทรีย์แบบไม่ใช้ออกซิเจน (Anaerobic Digestion) เช่น จากมูลสัตว์หรือน้ำเสียอุตสาหกรรม ได้ก๊าซมีเทนเป็นองค์ประกอบหลักซึ่งสามารถนำไปเผาไหม้ในเครื่องยนต์สันดาปภายในหรือกังหันก๊าซเพื่อผลิตไฟฟ้า ต่างจากชีวมวลแบบเผาไหม้โดยตรงที่ใช้ความร้อนจากการเผาวัสดุแข็งไปต้มน้ำผลิตไอน้ำ', 'กระบวนการผลิตก๊าซชีวภาพยังช่วยจัดการของเสียอินทรีย์ไปพร้อมกัน ทำให้เป็นทางเลือกที่น่าสนใจสำหรับฟาร์มปศุสัตว์ขนาดใหญ่หรือโรงงานแปรรูปอาหารที่มีของเสียอินทรีย์ปริมาณมาก', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'พลังงานก๊าซชีวภาพ (Biogas) แตกต่างจากพลังงานชีวมวลแบบเผาไหม้โดยตรงอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'โรงไฟฟ้าพลังน้ำขนาดเล็ก (Small Hydropower) มีหลักการผลิตไฟฟ้าแตกต่างจากโรงไฟฟ้าพลังน้ำขนาดใหญ่ในแง่ผลกระทบต่อสิ่งแวดล้อมอย่างไร', 'โรงไฟฟ้าพลังน้ำขนาดเล็กมักใช้หลักการผันน้ำบางส่วนจากลำน้ำธรรมชาติผ่านท่อส่งน้ำไปยังกังหันน้ำ (Run-of-river) โดยไม่ต้องสร้างเขื่อนกักเก็บน้ำขนาดใหญ่ ทำให้ผลกระทบต่อระบบนิเวศและการอพยพของประชากรในพื้นที่น้อยกว่าโรงไฟฟ้าพลังน้ำขนาดใหญ่ที่ต้องสร้างอ่างเก็บน้ำขนาดมหาศาล', 'อย่างไรก็ตาม กำลังผลิตไฟฟ้าของโรงไฟฟ้าพลังน้ำขนาดเล็กมักแปรผันตามปริมาณน้ำในลำน้ำธรรมชาติที่เปลี่ยนแปลงตามฤดูกาล ทำให้ไม่สามารถควบคุมการผลิตไฟฟ้าได้อิสระเท่าโรงไฟฟ้าพลังน้ำขนาดใหญ่ที่มีอ่างเก็บน้ำสำหรับบริหารจัดการปริมาณน้ำได้', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'โรงไฟฟ้าพลังน้ำขนาดเล็ก (Small Hydropower) มีหลักการผลิตไฟฟ้าแตกต่างจากโรงไฟฟ้าพลังน้ำขนาดใหญ่ในแง่ผลกระทบต่อสิ่งแวดล้อมอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดพลังงานทดแทนประเภทแสงอาทิตย์และลมจึงถูกจัดเป็นพลังงานที่มีความผันแปร (Intermittent/Variable Renewable Energy) ซึ่งสร้างความท้าทายต่อระบบไฟฟ้ากำลัง', 'เพราะกำลังผลิตไฟฟ้าขึ้นอยู่กับสภาพอากาศธรรมชาติที่ไม่สามารถควบคุมได้ เช่น ความเข้มแสงอาทิตย์หรือความเร็วลม ซึ่งเปลี่ยนแปลงตลอดเวลาและคาดการณ์ได้ไม่แม่นยำสมบูรณ์ ต่างจากโรงไฟฟ้าแบบดั้งเดิมที่สามารถควบคุมกำลังผลิตได้ตามต้องการ ความผันแปรนี้สร้างความท้าทายต่อการรักษาสมดุลของระบบไฟฟ้ากำลังที่ต้องการความสมดุลระหว่างการผลิตและการใช้ไฟฟ้าตลอดเวลา', 'การแก้ปัญหานี้ต้องอาศัยหลายมาตรการร่วมกัน เช่น การพยากรณ์สภาพอากาศที่แม่นยำ ระบบกักเก็บพลังงาน การเชื่อมโยงระบบไฟฟ้าในพื้นที่กว้างเพื่อกระจายความเสี่ยง และการมีกำลังผลิตสำรองที่ตอบสนองได้รวดเร็วเพื่อชดเชยความผันแปร', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดพลังงานทดแทนประเภทแสงอาทิตย์และลมจึงถูกจัดเป็นพลังงานที่มีความผันแปร (Intermittent/Variable Renewable Energy) ซึ่งสร้างความท้าทายต่อระบบไฟฟ้ากำลัง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ตัวประกอบกำลังการผลิต (Capacity Factor) ของโรงไฟฟ้าพลังงานทดแทนคืออะไร และมีความสำคัญอย่างไรในการวางแผนระบบไฟฟ้ากำลัง', 'คืออัตราส่วนระหว่างพลังงานไฟฟ้าที่ผลิตได้จริงตลอดปีต่อพลังงานไฟฟ้าสูงสุดที่จะผลิตได้หากทำงานเต็มพิกัดตลอดเวลาทั้งปี โรงไฟฟ้าพลังงานแสงอาทิตย์และลมมักมี Capacity Factor ต่ำกว่าโรงไฟฟ้าเชื้อเพลิงฟอสซิลหรือนิวเคลียร์อย่างมาก เนื่องจากความผันแปรตามธรรมชาติ', 'ค่านี้มีความสำคัญในการวางแผนระบบไฟฟ้ากำลัง เพราะแม้จะติดตั้งกำลังผลิตพลังงานทดแทนตามพิกัด (Installed Capacity) จำนวนมาก แต่พลังงานไฟฟ้าที่ผลิตได้จริงตลอดปีอาจต่ำกว่าที่คาดหวังหากไม่พิจารณา Capacity Factor ที่แท้จริงของแต่ละเทคโนโลยี', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ตัวประกอบกำลังการผลิต (Capacity Factor) ของโรงไฟฟ้าพลังงานทดแทนคืออะไร และมีความสำคัญอย่างไรในการวางแผนระบบไฟฟ้ากำลัง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'มาตรฐาน IEC 61215 และ IEC 61730 ที่เกี่ยวข้องกับแผงโซลาร์เซลล์ ครอบคลุมการทดสอบด้านใดตามลำดับ', 'IEC 61215 ครอบคลุมการทดสอบคุณสมบัติการออกแบบและอนุมัติแบบ (Design Qualification) เพื่อยืนยันว่าแผงมีความทนทานเพียงพอต่อสภาพแวดล้อมการใช้งานจริง เช่น การทดสอบความร้อน ความชื้น และรอบการเปลี่ยนแปลงอุณหภูมิ ส่วน IEC 61730 ครอบคลุมด้านความปลอดภัยทางไฟฟ้าและทางกล เพื่อยืนยันว่าแผงไม่ก่อให้เกิดอันตรายจากไฟฟ้าช็อตหรือไฟไหม้ในการใช้งานปกติ', 'การเลือกแผงโซลาร์เซลล์ที่ผ่านมาตรฐานทั้งสองฉบับนี้เป็นข้อพิจารณาสำคัญในการเลือกซื้อผลิตภัณฑ์ เพื่อความมั่นใจในความทนทานและความปลอดภัยของแผงตลอดอายุการใช้งานที่ยาวนานหลายสิบปี', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'มาตรฐาน IEC 61215 และ IEC 61730 ที่เกี่ยวข้องกับแผงโซลาร์เซลล์ ครอบคลุมการทดสอบด้านใดตามลำดับ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการทำความสะอาดแผงโซลาร์เซลล์เป็นระยะจึงมีความสำคัญต่อผลผลิตพลังงานที่ได้', 'ฝุ่นละออง มลภาวะ หรือมูลนกที่สะสมบนผิวแผงจะบดบังแสงอาทิตย์บางส่วนไม่ให้ตกกระทบเซลล์ ทำให้ผลผลิตพลังงานลดลง ในบางพื้นที่ที่มีฝุ่นมากหรือฝนตกน้อย ผลกระทบจากความสกปรกสะสม (Soiling Loss) อาจมีนัยสำคัญต่อผลผลิตพลังงานรายปีของระบบ', 'ความถี่ในการทำความสะอาดที่เหมาะสมขึ้นอยู่กับสภาพแวดล้อมของพื้นที่ติดตั้ง เช่น พื้นที่ใกล้ถนนฝุ่นหรือใกล้ทะเลที่มีคราบเกลืออาจต้องทำความสะอาดบ่อยกว่าพื้นที่ทั่วไป ต้องชั่งน้ำหนักระหว่างต้นทุนการทำความสะอาดกับผลผลิตพลังงานที่เพิ่มขึ้น', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการทำความสะอาดแผงโซลาร์เซลล์เป็นระยะจึงมีความสำคัญต่อผลผลิตพลังงานที่ได้'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการออกแบบระบบระบายอากาศใต้แผงโซลาร์เซลล์ (Air Gap) จึงมีผลต่อประสิทธิภาพการผลิตไฟฟ้า', 'เนื่องจากประสิทธิภาพของแผงลดลงเมื่ออุณหภูมิสูงขึ้นตามค่าสัมประสิทธิ์อุณหภูมิ การมีช่องว่างอากาศที่เพียงพอใต้แผงช่วยให้อากาศไหลเวียนระบายความร้อนออกจากด้านหลังแผงได้ดีขึ้น ลดอุณหภูมิของแผงและช่วยรักษาประสิทธิภาพการผลิตไฟฟ้าให้สูงขึ้นเมื่อเทียบกับการติดตั้งแผงชิดกับพื้นผิวหลังคาโดยไม่มีช่องว่างอากาศ', 'การติดตั้งแผงแบบยกสูงจากหลังคา (Rack Mounted) จึงมักให้ผลผลิตพลังงานดีกว่าการติดตั้งแบบแนบชิดกับหลังคา (Flush Mounted) แม้ในพื้นที่ที่มีความเข้มแสงเท่ากัน เนื่องจากการระบายความร้อนที่ดีกว่า', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการออกแบบระบบระบายอากาศใต้แผงโซลาร์เซลล์ (Air Gap) จึงมีผลต่อประสิทธิภาพการผลิตไฟฟ้า'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดในการออกแบบระบบโซลาร์เซลล์ จึงต้องพิจารณาแรงดันวงจรเปิดสูงสุด (Maximum Open Circuit Voltage) ที่อาจเกิดขึ้นในสภาวะอุณหภูมิต่ำ', 'เพราะแรงดันวงจรเปิดของแผงโซลาร์เซลล์มีค่าสูงขึ้นเมื่ออุณหภูมิลดลง (ตรงข้ามกับกำลังไฟฟ้าที่ลดลงเมื่ออุณหภูมิสูงขึ้น) ในสภาวะอุณหภูมิต่ำมากหรือช่วงเช้าที่แผงยังไม่ได้รับความร้อนจากแสงอาทิตย์ แรงดันของอาร์เรย์ที่ต่ออนุกรมอาจสูงเกินพิกัดแรงดันสูงสุดที่อินเวอร์เตอร์หรืออุปกรณ์อื่นในระบบสามารถรองรับได้', 'การคำนวณจำนวนแผงสูงสุดที่ต่ออนุกรมได้จึงต้องพิจารณาแรงดันวงจรเปิดที่อุณหภูมิต่ำสุดที่อาจเกิดขึ้นในพื้นที่ติดตั้ง ไม่ใช่พิจารณาเพียงแรงดันที่สภาวะทดสอบมาตรฐานเท่านั้น เพื่อความปลอดภัยของระบบในทุกสภาวะที่อาจเกิดขึ้นจริง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดในการออกแบบระบบโซลาร์เซลล์ จึงต้องพิจารณาแรงดันวงจรเปิดสูงสุด (Maximum Open Circuit Voltage) ที่อาจเกิดขึ้นในสภาวะอุณหภูมิต่ำ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดสายไฟที่ใช้เชื่อมต่อแผงโซลาร์เซลล์ (Solar Cable หรือ PV Wire) จึงต้องมีคุณสมบัติทนต่อรังสียูวีและสภาพอากาศเป็นพิเศษ', 'เพราะสายไฟที่เชื่อมต่อแผงโซลาร์เซลล์มักติดตั้งอยู่กลางแจ้งตลอดเวลา สัมผัสกับแสงแดด ความร้อน และความชื้นโดยตรงตลอดอายุการใช้งานของระบบที่ยาวนานหลายสิบปี ฉนวนของสายไฟทั่วไปที่ไม่ได้ออกแบบมาสำหรับใช้งานกลางแจ้งระยะยาวอาจเสื่อมสภาพอย่างรวดเร็วจากรังสียูวีและความร้อนสะสม', 'สายไฟชนิด Solar Cable จึงมักผลิตด้วยวัสดุฉนวนพิเศษที่มีความทนทานต่อรังสียูวีสูง และมักมีพิกัดอุณหภูมิใช้งานที่กว้างกว่าสายไฟทั่วไป เพื่อรองรับสภาพแวดล้อมการติดตั้งกลางแจ้งอย่างเหมาะสม', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดสายไฟที่ใช้เชื่อมต่อแผงโซลาร์เซลล์ (Solar Cable หรือ PV Wire) จึงต้องมีคุณสมบัติทนต่อรังสียูวีและสภาพอากาศเป็นพิเศษ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดในการติดตั้งระบบโซลาร์เซลล์บนหลังคา จึงต้องพิจารณาโครงสร้างและน้ำหนักบรรทุกของหลังคาเดิมก่อนติดตั้ง', 'เพราะแผงโซลาร์เซลล์และโครงยึดมีน้ำหนักเพิ่มเติมที่หลังคาต้องรองรับ นอกเหนือจากน้ำหนักโครงสร้างเดิมและน้ำหนักบรรทุกจร เช่น แรงลมที่กระทำต่อแผง หากโครงสร้างหลังคาเดิมไม่ได้ออกแบบมาเผื่อน้ำหนักส่วนนี้ อาจเกิดความเสี่ยงต่อความเสียหายของโครงสร้างหลังคาได้', 'การประเมินโครงสร้างหลังคาก่อนติดตั้งจึงเป็นขั้นตอนสำคัญที่ต้องดำเนินการโดยวิศวกรโครงสร้างร่วมกับวิศวกรไฟฟ้า เพื่อยืนยันว่าหลังคาสามารถรองรับน้ำหนักเพิ่มเติมได้อย่างปลอดภัยตลอดอายุการใช้งานของระบบ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดในการติดตั้งระบบโซลาร์เซลล์บนหลังคา จึงต้องพิจารณาโครงสร้างและน้ำหนักบรรทุกของหลังคาเดิมก่อนติดตั้ง'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการติดตั้งระบบสายดินและป้องกันฟ้าผ่าสำหรับระบบโซลาร์เซลล์จึงมีความสำคัญเป็นพิเศษ', 'เพราะแผงโซลาร์เซลล์มักติดตั้งในตำแหน่งที่สูงและเปิดโล่งกลางแจ้ง ซึ่งมีความเสี่ยงสูงต่อการถูกฟ้าผ่าโดยตรงหรือได้รับผลกระทบจากแรงดันเหนี่ยวนำจากฟ้าผ่าใกล้เคียง โครงสร้างโลหะของแผงและระบบสายไฟที่เชื่อมต่อกันเป็นระยะทางยาวอาจเป็นเส้นทางนำกระแสฟ้าผ่าเข้าสู่อาคารได้หากไม่มีการป้องกันที่เหมาะสม', 'การออกแบบระบบป้องกันจึงต้องพิจารณาทั้งการต่อกราวด์โครงสร้างแผงและโครงยึดอย่างเหมาะสม รวมถึงการติดตั้งอุปกรณ์ป้องกันแรงดันเกินชั่วครู่ (Surge Protective Device) ทั้งด้าน DC และ AC ของระบบ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการติดตั้งระบบสายดินและป้องกันฟ้าผ่าสำหรับระบบโซลาร์เซลล์จึงมีความสำคัญเป็นพิเศษ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการเชื่อมต่อระบบผลิตไฟฟ้าพลังงานทดแทนกระจายตัวจำนวนมากเข้ากับระบบจำหน่ายไฟฟ้า จึงอาจก่อให้เกิดปัญหาแรงดันเกินในสายจำหน่ายในบางช่วงเวลา', 'เพราะในช่วงเวลาที่มีการผลิตไฟฟ้าจากระบบพลังงานทดแทนสูงมาก (เช่น ช่วงเที่ยงที่แสงแดดจัด) แต่ความต้องการใช้ไฟฟ้าในพื้นที่นั้นต่ำ กระแสไฟฟ้าส่วนเกินจะไหลย้อนกลับเข้าสู่ระบบจำหน่าย ทำให้แรงดันไฟฟ้าในสายจำหน่ายบริเวณนั้นสูงขึ้นเกินเกณฑ์ปกติ โดยเฉพาะในพื้นที่ปลายสายที่ห่างจากหม้อแปลงจำหน่ายหลัก', 'ปัญหานี้เป็นความท้าทายสำคัญของระบบไฟฟ้าที่มีการติดตั้งโซลาร์รูฟท็อปจำนวนมากในพื้นที่เดียวกัน ซึ่งอาจต้องอาศัยมาตรการแก้ไข เช่น การจำกัดปริมาณกำลังผลิตสูงสุดที่อนุญาตให้เชื่อมต่อ หรือการปรับปรุงโครงสร้างระบบจำหน่ายให้รองรับการไหลของกระแสสองทิศทางได้ดีขึ้น', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการเชื่อมต่อระบบผลิตไฟฟ้าพลังงานทดแทนกระจายตัวจำนวนมากเข้ากับระบบจำหน่ายไฟฟ้า จึงอาจก่อให้เกิดปัญหาแรงดันเกินในสายจำหน่ายในบางช่วงเวลา'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการประเมินศักยภาพพลังงานลมหรือแสงอาทิตย์ของพื้นที่ก่อนลงทุนโครงการขนาดใหญ่ จึงต้องอาศัยข้อมูลการตรวจวัดภาคสนามระยะยาว แทนที่จะใช้เพียงข้อมูลจากแผนที่ศักยภาพทั่วไป', 'เพราะข้อมูลจากแผนที่ศักยภาพทั่วไปมักมีความละเอียดเชิงพื้นที่จำกัดและอาจไม่สะท้อนสภาพภูมิประเทศเฉพาะจุดที่ต้องการติดตั้งจริง เช่น อิทธิพลจากภูมิประเทศท้องถิ่นหรือสิ่งกีดขวางเฉพาะจุด การตรวจวัดภาคสนามระยะยาว (มักอย่างน้อย 1 ปีเต็ม) ช่วยให้ได้ข้อมูลที่แม่นยำเฉพาะพื้นที่ ครอบคลุมความผันแปรตามฤดูกาลที่แท้จริง', 'ความแม่นยำของข้อมูลศักยภาพพลังงานมีผลโดยตรงต่อความแม่นยำในการประเมินผลตอบแทนทางเศรษฐศาสตร์ของโครงการ ซึ่งมีมูลค่าการลงทุนสูงมาก การลงทุนในการตรวจวัดข้อมูลที่แม่นยำจึงมักคุ้มค่าเมื่อเทียบกับความเสี่ยงจากการประเมินผิดพลาด', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการประเมินศักยภาพพลังงานลมหรือแสงอาทิตย์ของพื้นที่ก่อนลงทุนโครงการขนาดใหญ่ จึงต้องอาศัยข้อมูลการตรวจวัดภาคสนามระยะยาว แทนที่จะใช้เพียงข้อมูลจากแผนที่ศักยภาพทั่วไป'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการวางแผนพัฒนาระบบไฟฟ้ากำลังในอนาคตที่มีสัดส่วนพลังงานทดแทนสูงขึ้นเรื่อยๆ จึงต้องพิจารณาความยืดหยุ่นของระบบ (System Flexibility) เป็นปัจจัยสำคัญ', 'เพราะสัดส่วนพลังงานทดแทนที่มีความผันแปรสูงขึ้น ทำให้ระบบไฟฟ้ากำลังต้องการความสามารถในการปรับสมดุลระหว่างการผลิตและการใช้ไฟฟ้าที่รวดเร็วและยืดหยุ่นมากขึ้น ทั้งจากโรงไฟฟ้าสำรองที่ตอบสนองเร็ว ระบบกักเก็บพลังงาน การบริหารจัดการด้านความต้องการใช้ไฟฟ้า (Demand Response) และการเชื่อมโยงระบบไฟฟ้าระหว่างพื้นที่', 'การเปลี่ยนผ่านสู่ระบบไฟฟ้าที่มีสัดส่วนพลังงานทดแทนสูงจึงไม่ใช่เพียงการเพิ่มกำลังผลิตพลังงานทดแทนเท่านั้น แต่ต้องพัฒนาโครงสร้างพื้นฐานและกลไกการบริหารจัดการระบบทั้งหมดให้มีความยืดหยุ่นเพียงพอรองรับความท้าทายที่มาพร้อมกับความผันแปรของแหล่งพลังงานเหล่านี้ไปพร้อมกัน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการวางแผนพัฒนาระบบไฟฟ้ากำลังในอนาคตที่มีสัดส่วนพลังงานทดแทนสูงขึ้นเรื่อยๆ จึงต้องพิจารณาความยืดหยุ่นของระบบ (System Flexibility) เป็นปัจจัยสำคัญ'
  );

commit;

-- ---------- ตรวจสอบผลลัพธ์ ----------
select c.name_th as category, count(q.id) as question_count
from categories c
left join questions q on q.category_id = c.id
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'renewable_energy'
group by c.name_th;
